//  Tests of HexDecode: at the last position of each span of hex digits (upper
//  or lower case, of at most 6 significant digits, after any leading zeros), the
//  21-bit value of the span; elsewhere, the basis copied.  The basis and expected
//  streams are given bit by bit (bit 0 first), generated from the texts in the
//  comments.

#include <testing/testing.h>
#include <kernel/util/hex_convert.h>
#include <kernel/pipeline/program_builder.h>

using namespace kernel;
using namespace testing;

//  'U+41 7a 0;Ff 1F600 10FFFF.abc' (29 positions)
auto hexdecode_small_basis = BinaryStreamSet({
    "11010110010001000001000000101",
    "01000100011100110000011111011",
    "10100100001100110000011111000",
    "01000000010000000000000001000",
    "10110100110001011101100000000",
    "01111111110111011111100001111",
    "10000010001100100000011110111",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000"});
auto hexdecode_small_spans = BinaryStreamSet({"00110110101101111101111110111"});
auto hexdecode_small_expected = BinaryStreamSet({
    "11010100010101000001000010100",
    "01000110011100110000011111010",
    "10100100001100110000011111001",
    "01000010010100000000000011001",
    "10100110010101011001100010001",
    "01101111010111011011100011111",
    "10010010001100100000011110110",
    "00000000000100000000000010001",
    "00000000000000000000000010000",
    "00000000000000000100000010001",
    "00000000000000000100000010000",
    "00000000000000000000000010001",
    "00000000000000000100000010000",
    "00000000000000000100000010000",
    "00000000000000000100000010000",
    "00000000000000000100000010000",
    "00000000000000000100000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000000000",
    "00000000000000000000000010000"});
TEST_CASE(hexdecode_small, hexdecode_small_basis, hexdecode_small_spans, hexdecode_small_expected) {
    auto Result = P.CreateStreamSet(21);
    P.CreateKernelCall<HexDecode>(Input<0>(T), Input<1>(T), Result);
    AssertEQ(P, Result, Input<2>(T));
}

