//  Tests of DecimalDecode: at the last position of each span of decimal digits
//  (at most 8), its value if at most 10FFFF (1114111), and otherwise a mark in
//  the overflow stream (the basis copied).

//  '&#65;0 1114111 1114112 00000065 99999999 x128512' (48 positions)
auto decdecode_small_basis = BinaryStreamSet({
    "010110011101110111011000000000101111111100100110",
    "111010000000000000000100000001000000000000010001",
    "101100000010000000100000000001100000000000000100",
    "000010000000000000000000000000001111111101001000",
    "001111011111110111111101111111101111111101111111",
    "111111111111111111111111111111111111111111111111",
    "000000000000000000000000000000000000000001000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000"});
auto decdecode_small_spans = BinaryStreamSet({"001101011111110111111101111111101111111100111111"});
auto decdecode_small_expected = BinaryStreamSet({
    "010110011101110111011000000000101111111100100110",
    "111010000000010000000100000001000000000000010000",
    "101000000010010000100000000001000000000000000100",
    "000010000000010000000000000000001111111101001000",
    "001010011111110111111101111111001111111101111110",
    "111010111111111111111111111111011111111111111110",
    "000100000000010000000000000000100000000001000000",
    "000000000000010000000000000000000000000000000000",
    "000000000000010000000000000000000000000000000000",
    "000000000000010000000000000000000000000000000001",
    "000000000000010000000000000000000000000000000001",
    "000000000000010000000000000000000000000000000000",
    "000000000000010000000000000000000000000000000001",
    "000000000000010000000000000000000000000000000001",
    "000000000000010000000000000000000000000000000001",
    "000000000000010000000000000000000000000000000001",
    "000000000000000000000000000000000000000000000001",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000000000000000000000000000000000000000",
    "000000000000010000000000000000000000000000000000"});
auto decdecode_small_overflow = BinaryStreamSet({"000000000000000000000100000000000000000100000000"});
TEST_CASE(decdecode_small, decdecode_small_basis, decdecode_small_spans, decdecode_small_expected, decdecode_small_overflow) {
    auto Result = P.CreateStreamSet(21);
    auto Overflow = P.CreateStreamSet(1);
    P.CreateKernelCall<DecimalDecode>(Input<0>(T), Input<1>(T), Result, Overflow);
    AssertEQ(P, Result, Input<2>(T));
    AssertEQ(P, Overflow, Input<3>(T));
}

